SELECT 
FROM user_sheets s LEFT JOIN jangdans j ON j.id = s.jangdan_id
WHERE s.id = #{sheetId} AND s.user_id = #{userId}

SELECT 
FROM user_sheets s LEFT JOIN jangdans j ON j.id = s.jangdan_id
WHERE s.user_id = #{userId}
AND s.kind = #{kind}
ORDER BY s.updated_at DESC, s.id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE user_sheets
SET title = #{title}, status = #{status}, jangdan_id = #{jangdanId}, bpm = #{bpm}, bpm_unit = #{bpmUnit}, column_count = #{columnCount},
    score_version = score_version + 1, score_json = #{scoreJson}, note_count = #{noteCount}, pending_cell_count = 0,
    draft_json = NULL, draft_revision = 0, draft_base_version = NULL, draft_saved_at = NULL, updated_at = #{updatedAt}
WHERE id = #{sheetId} AND user_id = #{userId} AND score_version = #{baseScoreVersion}

